class Hold(RuntimeError):
    pass


class Deadline(BaseException):
    pass


def require(value, code):
    if not value:
        raise Hold(code)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def emit(name, value):
    raw = json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(',', ':'), allow_nan=False)
    require(len(raw.encode()) <= 65536, 'OUTPUT_BOUND')
    print('NOX_MAINT_' + name + '=' + raw, flush=True)


def safe_error(error):
    return str(error) if isinstance(error, Hold) and re.fullmatch('[A-Z0-9_]{1,90}', str(error)) else type(error).__name__


def embedded_observer():
    raw = base64.b64decode(OBSERVER_BASE64, validate=True)
    require(len(raw) <= 100000 and sha(raw) == OBSERVER_SHA256, 'OBSERVER_PIN')
    module = types.ModuleType('_nox_reviewed_readonly_observer')
    module.__file__ = '<reviewed-owner_systemic_relay_observe.py>'
    exec(compile(raw, module.__file__, 'exec'), module.__dict__)
    return module


def protected(observer):
    rows = {}
    for name, expected in EXPECTED_PROCESSES.items():
        actual = observer.process(expected['pid'])
        rows[name] = {'expected': expected,
                      'observed': {key: actual.get(key) for key in ('pid', 'start_ticks', 'ppid', 'pgrp', 'state')},
                      'matches': actual.get('state') in ('R', 'S', 'D', 'I')
                                 and all(actual.get(key) == value for key, value in expected.items())}
    return rows


def metadata(info):
    kind = ('directory' if stat.S_ISDIR(info.st_mode) else 'symlink' if stat.S_ISLNK(info.st_mode)
            else 'regular' if stat.S_ISREG(info.st_mode) else 'other')
    return {'type': kind, 'uid': info.st_uid, 'gid': info.st_gid, 'mode': info.st_mode & 0o7777,
            'device': info.st_dev, 'inode': info.st_ino, 'nlink': info.st_nlink}


def directory_metadata(path):
    result = {'path': path, 'ancestors': [], 'present': None, 'contents_read': False}
    fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    current = Path('/')
    try:
        for part in Path(path).parts[1:]:
            current /= part
            try:
                before = os.stat(part, dir_fd=fd, follow_symlinks=False)
            except FileNotFoundError:
                result.update(present=False, first_absent_path=str(current), state='ABSENT')
                return result
            row = {'path': str(current), 'lstat': metadata(before)}
            result['ancestors'].append(row)
            if not stat.S_ISDIR(before.st_mode):
                result.update(present=str(current) == path, state='NON_DIRECTORY_NOFOLLOW')
                return result
            child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=fd)
            try:
                row['fstat'] = metadata(os.fstat(child))
                after = metadata(os.stat(part, dir_fd=fd, follow_symlinks=False))
                row['lstat_fstat_match'] = row['lstat'] == row['fstat'] == after
                require(row['lstat_fstat_match'], 'DIRECTORY_CHANGED')
            except BaseException:
                os.close(child)
                raise
            os.close(fd)
            fd = child
        result.update(present=True, state='OBSERVED', lstat=result['ancestors'][-1]['lstat'],
                      fstat=result['ancestors'][-1]['fstat'])
        return result
    except (OSError, Hold) as error:
        result.update(state='UNAVAILABLE', error=safe_error(error))
        return result
    finally:
        os.close(fd)


def route_source_evidence(observer):
    files = []
    for name, expected in SOURCE_PINS.items():
        raw, info = observer.safe_read(ROOT / 'scripts' / name, 262144)
        row = {'name': name, 'sha256': sha(raw), 'bytes': len(raw), 'metadata': metadata(info),
               'matches_expected': sha(raw) == expected, 'body_exported': False}
        require(row['matches_expected'], 'ROUTE_SOURCE_CHANGED')
        tree = ast.parse(raw)
        text = raw.decode('utf-8')
        row['static_mounts'] = []
        for node in ast.walk(tree):
            if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                    and node.func.attr == 'mount' and node.args and isinstance(node.args[0], ast.Constant)
                    and node.args[0].value == '/nox-web-v29'):
                segment = ast.get_source_segment(text, node)
                row['static_mounts'].append({'path': '/nox-web-v29', 'line': node.lineno,
                    'call_sha256': sha(segment.encode()) if segment is not None else None,
                    'uses_owner_static': any(isinstance(child, ast.Name) and child.id == '_OwnerStatic'
                                             for child in ast.walk(node))})
        require(len(row['static_mounts']) <= 8, 'STATIC_MOUNT_BOUND')
        classes = [node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == '_OwnerStatic']
        row['owner_static_class_count'] = len(classes)
        row['owner_static_methods'] = []
        for node in classes:
            for child in node.body:
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name in ('__init__', '__call__'):
                    segment = ast.get_source_segment(text, child)
                    row['owner_static_methods'].append({'name': child.name, 'line': child.lineno,
                        'sha256': sha(segment.encode()) if segment is not None else None,
                        'calls_auth': any(isinstance(item, ast.Attribute) and item.attr == '_auth' for item in ast.walk(child)),
                        'calls_unauthorized': any(isinstance(item, ast.Attribute) and item.attr == '_unauthorized' for item in ast.walk(child))})
        require(len(row['owner_static_methods']) <= 4, 'STATIC_METHOD_BOUND')
        files.append(row)
    return files


def listener_owned(observer, pid, port):
    first = observer.process(pid)
    require(first.get('state') in ('R', 'S', 'D', 'I'), 'LISTENER_PROCESS')
    owners = set()
    paths = list((Path('/proc') / str(pid) / 'fd').iterdir())
    require(len(paths) <= 4096, 'LISTENER_FD_BOUND')
    for path in paths:
        try:
            target = os.readlink(path)
        except FileNotFoundError:
            continue
        match = re.fullmatch(r'socket:\[(\d+)\]', target)
        if match:
            owners.add(match[1])
    listeners = set()
    for name in ('tcp', 'tcp6'):
        with open('/proc/net/' + name, 'rb', buffering=0) as stream:
            chunks, total = [], 0
            while True:
                chunk = stream.read(min(65536, 2097153 - total))
                total += len(chunk)
                require(total <= 2097152, 'LISTENER_TABLE_BOUND')
                if not chunk:
                    break
                chunks.append(chunk)
            raw = b''.join(chunks)
        require(len(raw) <= 2097152, 'LISTENER_TABLE_BOUND')
        for line in raw.decode('ascii').splitlines()[1:]:
            fields = line.split()
            if len(fields) >= 10 and fields[3] == '0A' and int(fields[1].rsplit(':', 1)[1], 16) == port:
                listeners.add(fields[9])
    second = observer.process(pid)
    require(listeners and listeners <= owners and all(first.get(key) == second.get(key)
            for key in ('pid', 'start_ticks', 'ppid', 'pgrp')), 'LISTENER_OWNERSHIP')
    return {'pid': pid, 'start_ticks': first['start_ticks'], 'port': port, 'verified': True}


def safe_header(value, kind):
    if value is None:
        return None
    value = value.strip().lower()
    if kind == 'content-type':
        value = value.split(';', 1)[0].strip()
        pattern = r'[a-z0-9!#$&^_.+/-]{1,100}'
    elif kind == 'content-encoding':
        pattern = r'[a-z0-9, -]{1,100}'
    else:
        pattern = r'[0-9]{1,12}'
    return value if re.fullmatch(pattern, value) else 'UNEXPECTED_HEADER_VALUE'


def observe_url(observer, route, protected_before, asset_sha):
    row = {**route, 'host': '127.0.0.1', 'method': 'GET', 'credentials_used': False,
           'body_exported': False, 'redirects_followed': False}
    connection = None
    try:
        identity = protected_before[route['service']]
        require(identity['matches'], 'PINNED_SERVICE_CHANGED')
        pid = identity['expected']['pid']
        row['listener_before'] = listener_owned(observer, pid, route['port'])
        connection = http.client.HTTPConnection('127.0.0.1', route['port'], timeout=3)
        connection.request('GET', route['path'], headers={'Connection': 'close',
                           'Accept-Encoding': 'identity', 'Cache-Control': 'no-cache'})
        response = connection.getresponse()
        row['status'] = response.status
        row['headers'] = {name: safe_header(response.getheader(name), name)
                         for name in ('content-type', 'content-encoding', 'content-length')}
        raw = response.read(65537)
        row['bytes_read'] = len(raw)
        complete = len(raw) <= 65536
        row['complete_body_within_bound'] = complete
        row['sha256'] = sha(raw) if complete else None
        row['javascript_content_type'] = row['headers']['content-type'] in (
            'application/javascript', 'text/javascript', 'application/x-javascript')
        row['matches_current_asset'] = (complete and response.status == 200 and sha(raw) == asset_sha
                                       and response.getheader('Content-Encoding', 'identity') == 'identity')
        row['listener_after'] = listener_owned(observer, pid, route['port'])
        row['state'] = 'OBSERVED' if complete else 'BODY_BOUND_EXCEEDED'
    except (OSError, ValueError, http.client.HTTPException, Hold) as error:
        row.update(state='UNAVAILABLE', error=safe_error(error))
    finally:
        if connection is not None:
            connection.close()
    return row


def main():
    previous = signal.getsignal(signal.SIGALRM)
    def expire(signum, frame):
        raise Deadline()
    signal.signal(signal.SIGALRM, expire)
    signal.setitimer(signal.ITIMER_REAL, 55)
    complete = False
    record = {'schema': 'NOX_CHAT_ASSET_ROUTE_OBSERVE_V1', 'read_only': True,
              'source_writes': 0, 'model_calls': 0, 'service_restarts': 0, 'credentials_used': False,
              'started_at': time.time(), 'source_observer_sha256': OBSERVER_SHA256}
    try:
        observer = embedded_observer()
        emit('ACCELERATION_DIRECTORY_OBSERVE', {'schema': 'NOX_ACCELERATION_DIRECTORY_OBSERVE_V1',
             'euid': os.geteuid(), 'egid': os.getegid(), 'python_version': list(sys.version_info[:3]),
             'directories': [directory_metadata(path) for path in DIRECTORIES],
             'created': False, 'permissions_changed': False, 'directory_contents_listed': False})
        observer.emit('SNAPSHOT_A', observer.runtime_snapshot())
        observer.worker_status_sample()
        observer.director_child_census()
        before = protected(observer)
        record['protected_before'] = before
        asset, info = observer.safe_read(ASSET, 65536)
        record['asset'] = {'path': str(ASSET), 'sha256': sha(asset), 'bytes': len(asset),
                           'metadata': metadata(info), 'matches_expected': sha(asset) == EXPECTED_ASSET}
        record['route_source_evidence'] = route_source_evidence(observer)
        record['routes'] = [observe_url(observer, route, before, sha(asset)) for route in ROUTES]
        proofs = observer.project_execution_readback()
        observer.project_workspace_census(proofs)
        observer.emit('LOCKS', observer.locks())
        time.sleep(6)
        observer.worker_status_sample()
        observer.director_child_census()
        observer.emit('SNAPSHOT_B', observer.runtime_snapshot())
        after = protected(observer)
        record['protected_after'] = after
        record['protected_stable'] = all(before[name]['matches'] and after[name]['matches']
                                        for name in EXPECTED_PROCESSES)
        asset_after, _ = observer.safe_read(ASSET, 65536)
        record['asset_unchanged'] = sha(asset_after) == sha(asset)
        record['state'] = 'READ_ONLY_OBSERVATION_COMPLETE'
        complete = True
    except BaseException as error:
        record.update(state='HOLD_READ_ONLY_OBSERVATION', reason=safe_error(error))
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous)
    record['finished_at'] = time.time()
    emit('CHAT_ASSET_ROUTE_OBSERVE', record)
    print('NOX_MAINT_INSPECT_COMPLETE=' + str(complete).lower(), flush=True)
    return 0 if complete else 2


if __name__ == '__main__':
    raise SystemExit(main())
